// Build English search query from company data
const empresa = $('🏢 Obtener Empresa G54').item.json.data;
const industry = (empresa.industry || '').toLowerCase();
const city = (empresa.base_city || '').split('/')[1]?.trim() || empresa.base_city || '';

// Map known industry terms to English search queries
const industryMap = {
  'embalaje': 'industrial packaging OR wooden crates OR crating',
  'crating': 'industrial crating OR wooden crates OR industrial packaging',
  'packaging': 'industrial packaging OR wooden crates',
  'logistic': 'logistics OR freight OR supply chain',
  'transport': 'freight transport OR logistics',
  'construction': 'construction industry OR building materials',
  'food': 'food industry OR food packaging',
  'tech': 'technology industry OR tech innovation',
};

let query = industry || 'business news'; // sin industria conocida: genérico, nunca el rubro de otro cliente
for (const [key, val] of Object.entries(industryMap)) {
  if (industry.includes(key)) {
    query = val;
    break;
  }
}

return [{ json: { newsapi_query: query } }];

// Extract titles from NewsAPI JSON response
const resp = $input.item.json;

const articles = resp.articles || [];
const titles = articles
  .filter(a => a.title && a.title !== '[Removed]')
  .slice(0, 8)
  .map((a, i) => `${i+1}. ${a.title} (${a.source?.name || ''})`);

const summary = titles.length > 0
  ? titles.join('\n')
  : 'No recent news found.';

return [{ json: {
  headlines: summary,
  count: titles.length
}}];

