const raw = $input.item.json.choices?.[0]?.message?.content || '{}';
let tema;
try { tema = JSON.parse(raw); }
catch(e) {
  const m = raw.match(/\{[\s\S]*?\}/);
  try { tema = m ? JSON.parse(m[0]) : {}; } catch(e2) { tema = {}; }
}
return [{ json: {
