  trend_keyword_en: tema.keyword_en  || ''
}}];

const tema = $('🔍 Parsear Tema Tendencia').item.json;
const verif = $input.item.json;

const totalResults = verif.totalResults || 0;
const THRESHOLD = 5; // mínimo artículos en últimos 3 días para confirmar tendencia

const esVerificada = tema.trend_topic && totalResults >= THRESHOLD;

return [{ json: {
  trend_topic:     tema.trend_topic,
  trend_keyword:   tema.trend_keyword,
  trend_justify:   tema.trend_justify,
  trend_platform:  tema.trend_platform,
  es_tendencia:    esVerificada,
  trend_verificada: esVerificada,
  trend_articulos_recientes: totalResults,
  trend_nota: esVerificada
    ? `Verificada: ${totalResults} artículos en últimos 3 días`
    : `No verificada: solo ${totalResults} artículos recientes (mínimo ${THRESHOLD})`
}}];

const cfg      = $('⚙️ Config G54').item.json;
const empRaw   = $('🏢 Obtener Empresa G54').item.json;
const estRaw   = $('🎯 Obtener Estrategia G54').item.json;
const kwRaw    = $('🔍 Obtener Keywords G54').item.json;
const ideasRaw = $('📋 Obtener Ideas Existentes (G54)').item.json;
const trend    = $('✅ Evaluar Verificación Tendencia').item?.json || {};

const emp = empRaw.data || empRaw || {};
const est = estRaw.data || estRaw || {};

if (!est || !est.objetivo) {
  throw new Error('No hay estrategia guardada para esta empresa — hay que correr el Strategist AI primero.');
}

// modo "semanal": el trigger automático — genera TODAS las ideas de la semana por plataforma.
// modo "regenerar": el cliente no le gustó una idea puntual pero quiere conservar su keyword —
//   genera 1 sola idea nueva para ese par keyword+plataforma exacto, sin tocar el resto del plan.
// modo "manual" (default): el botón de generar idea suelta del panel — genera 1 sola idea.
const webhookBody = $('🔔 Webhook: Generar Ideas').item.json.body || {};
const modo = webhookBody.modo === 'semanal' ? 'semanal'
  : webhookBody.modo === 'regenerar' ? 'regenerar'
  : 'manual';

const allKw = (kwRaw.data || kwRaw || []).filter(k => k.estado === 'activa');
const ideasExistentes = ideasRaw.data || (Array.isArray(ideasRaw) ? ideasRaw : []);
const keywordsUsadas = new Set(ideasExistentes.map(i => (i.keyword || '').toLowerCase().trim()).filter(Boolean));

const keywordsDisponibles = allKw
  .map(k => k.keyword)
  .filter(kw => kw && !keywordsUsadas.has(kw.toLowerCase().trim()));

const plataformasEstrategia = (est.plataformas && est.plataformas.length) ? est.plataformas : ['Instagram', 'Facebook'];

// --- Desglose por plataforma: parsea est.frecuencia formato "Facebook 3x/sem, Instagram 2x/sem" ---
function parsearDesglose(frecuenciaStr, plataformas) {
  const resultado = {};
  if (frecuenciaStr) {
    const regex = /([A-Za-zÀ-ÿ]+)\s*(\d+)\s*x\s*\/?\s*sem/gi;
    let m;
    while ((m = regex.exec(frecuenciaStr)) !== null) {
      const plat = plataformas.find(p => p.toLowerCase() === m[1].toLowerCase().trim());
      if (plat) resultado[plat] = parseInt(m[2], 10);
    }
  }
  // Fallback si no se pudo parsear nada del campo frecuencia: repartir parejo entre las plataformas
  if (Object.keys(resultado).length === 0) {
    const total = Number(cfg.G54_FRECUENCIA_SEMANAL) || 3;
    const base = Math.floor(total / plataformas.length);
    const resto = total % plataformas.length;
    plataformas.forEach((p, i) => { resultado[p] = base + (i < resto ? 1 : 0); });
  }
  return resultado;
}

let asignaciones;
let idea_id = null;
let usaTendencia = false;

if (modo === 'regenerar') {
  // Cupo fijo de 1: la keyword y plataforma ya vienen decididas por el panel — no se
  // excluyen por "ya usadas" (es intencional reusar la misma keyword) ni se reparte por desglose.
  idea_id = webhookBody.idea_id || null;
  if (!idea_id || !webhookBody.keyword || !webhookBody.platform) {
    throw new Error('modo=regenerar requiere idea_id, keyword y platform en el body del webhook.');
  }
  asignaciones = [{ keyword: webhookBody.keyword, platform: webhookBody.platform }];
} else {
  const desglose = parsearDesglose(est.frecuencia, plataformasEstrategia);

  // --- Armar los "cupos" (uno por idea a generar) según el modo ---
  let slots = [];
  if (modo === 'semanal') {
    for (const [plat, cantidad] of Object.entries(desglose)) {
      for (let i = 0; i < cantidad; i++) slots.push({ platform: plat });
    }
    if (slots.length === 0) slots.push({ platform: plataformasEstrategia[0] });
  } else {
    // manual: 1 sola idea, en la plataforma con más cupo semanal según la estrategia
    const platDefault = Object.entries(desglose).sort((a, b) => b[1] - a[1])[0]?.[0] || plataformasEstrategia[0];
    slots = [{ platform: platDefault }];
  }

  // Si hay tendencia verificada y hay más de 1 cupo en modo semanal, el último cupo se reserva para la tendencia
  usaTendencia = !!(trend.trend_verificada && trend.trend_topic) && slots.length > 1;
  const slotsKeyword = usaTendencia ? slots.slice(0, -1) : slots;

  // Asignar una keyword real a cada cupo (recicla desde el principio de la lista completa si no alcanzan las sin usar)
  let pool = keywordsDisponibles.length >= slotsKeyword.length ? keywordsDisponibles : allKw.map(k => k.keyword);
  if (pool.length === 0) {
    throw new Error('No hay keywords activas configuradas en G54 para esta empresa.');
  }
  asignaciones = slotsKeyword.map((slot, i) => ({ keyword: pool[i % pool.length], platform: slot.platform }));
}

const keywordsListado = asignaciones.map((a, i) => `${i + 1}. keyword: "${a.keyword}" → plataforma: ${a.platform}`).join('\n');

const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 1);
const weekNum = Math.ceil(((now - startOfYear) / 86400000 + startOfYear.getDay() + 1) / 7);

const prompt = `Actúa como especialista en contenido SEO/AEO para redes sociales B2B.

REGLA DE IDIOMA — OBLIGATORIA: cada keyword de la lista de abajo puede venir en un idioma distinto (ya viene en el idioma real que prefiere ese cliente o mercado, decidido antes de esta etapa). Para CADA idea que generes, escribe el "topic" y el "angulo" en el MISMO idioma exacto en que está escrita SU keyword — nunca traduzcas ni uses un solo idioma para todas las ideas del lote. Si una keyword está en inglés, esa idea va en inglés; si está en español, esa idea va en español; y así con cualquier otro idioma que reconozcas.

CONTEXTO DE LA EMPRESA:
Negocio: ${emp.name || ''}
Industria: ${emp.industry || ''}
Ciudad base: ${emp.base_city || ''}

ESTRATEGIA YA APROBADA (no la modifiques, solo síguela):
Objetivo: ${est.objetivo || ''}
Audiencia: ${est.audiencia || ''}
Tono: ${est.tono || ''}
Pilares de contenido: ${(est.pilares || []).join(', ')}
${modo === 'regenerar' ? '\nESTA ES UNA REGENERACIÓN: al cliente no le gustó la idea anterior para esta keyword, pero quiere conservar la keyword. Genera un título y ángulo DIFERENTES a lo obvio/genérico, con otro enfoque para la misma keyword.\n' : ''}
TU TAREA: generar EXACTAMENTE ${asignaciones.length} ideas — una por cada combinación de keyword+plataforma de esta lista, EN ESTE ORDEN, ya asignadas:
${keywordsListado}

REGLA ABSOLUTA DE COHERENCIA — proceso obligatorio KEYWORD → IDEA (nunca al revés):
1. Para cada keyword de la lista, primero identifica cuál es la intención de búsqueda real de ESA keyword específica.
2. Después crea un título de idea que responda DIRECTAMENTE a esa intención — mismo tema que la keyword, no un tema relacionado ni general de la empresa.
3. PROHIBIDO: inventar un título primero y después pegarle cualquier keyword de la lista solo porque sobraba. Cada keyword es el origen del título, no una etiqueta después del hecho.
4. Para cada idea agrega el campo "angulo": una frase corta que explique por qué ese título responde exactamente a esa keyword.
5. Respeta la plataforma ya asignada a cada keyword — no la cambies.

Entrega ÚNICAMENTE un JSON válido con esta estructura exacta (sin markdown, sin texto extra):
{
  "ideas": [
    {"keyword": "la keyword EXACTA tal como te la di", "topic": "título del post que responde a esa keyword", "angulo": "por qué este título responde a esta keyword", "tipo": "TOFU|MOFU|BOFU", "platform": "la plataforma ya asignada a esa keyword"}
  ]
}

Genera exactamente ${asignaciones.length} ideas, una por keyword, en el mismo orden de la lista, respetando la plataforma indicada para cada una.`;

return [{ json: {
  prompt,
  modo,
  idea_id,
  company_id: Number(cfg.G54_COMPANY_ID) || 1,
  asignaciones,
  weekNum,
  trend_verificada: usaTendencia,
  trend_topic: trend.trend_topic || '',
  trend_keyword: trend.trend_keyword || '',
  trend_justify: trend.trend_justify || '',
  trend_platform: trend.trend_platform || plataformasEstrategia[0],
}}];

