parameters.jsCode:
const ctx = $('🔧 Preparar Contexto Ideas').item.json;
const raw = $input.item.json.choices?.[0]?.message?.content
  || $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
  || '{}';

let parsed;
try { parsed = JSON.parse(raw); }
catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { parsed = m ? JSON.parse(m[0]) : {}; } catch (e2) { parsed = {}; }
}

const ideasRaw = Array.isArray(parsed.ideas) ? parsed.ideas : [];

// asignaciones = [{keyword, platform}] ya decididas por el contexto ANTES de llamar a la IA —
// la plataforma se fuerza desde aquí, nunca se confía en lo que la IA devuelva en ese campo.
const asignadas = new Map(ctx.asignaciones.map(a => [a.keyword.toLowerCase().trim(), a.platform]));

const ideasValidas = [];
const ideasDescartadas = [];

for (const idea of ideasRaw) {
  const kw = (idea.keyword || '').toLowerCase().trim();
  const topic = (idea.topic || '').trim();
  if (!kw || !asignadas.has(kw)) {
    ideasDescartadas.push({ motivo: 'keyword no coincide con la lista asignada', idea });
    continue;
  }
  if (!topic || !idea.angulo) {
    ideasDescartadas.push({ motivo: 'falta topic o angulo de justificación', idea });
    continue;
  }
  ideasValidas.push({
    topic,
    tipo: idea.tipo || 'TOFU',
    keyword: idea.keyword,
    platform: asignadas.get(kw), // plataforma forzada, no la de la IA
    semana: ctx.weekNum,
    estado: 'pendiente',
    es_tendencia: false,
    angulo: idea.angulo,
  });
}

// Agregar la idea de tendencia si fue verificada y el modo la incluyó como slot
// (ya viene con su propia justificación del análisis de noticias, no pasa por la IA de ideas)
if (ctx.trend_verificada && ctx.trend_topic) {
  ideasValidas.push({
    topic: ctx.trend_topic,
    tipo: 'TOFU',
    keyword: ctx.trend_keyword || '',
    platform: ctx.trend_platform,
    semana: ctx.weekNum,
    estado: 'pendiente',
    es_tendencia: true,
    angulo: ctx.trend_justify || '',
  });
}

return [{ json: {
  company_id: ctx.company_id,
  modo: ctx.modo,
  idea_id: ctx.idea_id || null,
  ideas: ideasValidas,
  ideas_descartadas_count: ideasDescartadas.length,
  ideas_descartadas: ideasDescartadas,
}}];
